<template><section class="sound-settings" aria-label="사운드 설정"><h3>사운드</h3><label class="sound-check"><input type="checkbox" :checked="music" @change="$emit('music',($event.target as HTMLInputElement).checked)"> 배경음 켜기</label><label>배경음 선택<select :value="modelValue.theme" @change="change('theme',($event.target as HTMLSelectElement).value)"><option value="classic">클래식 · 코로베이니키 칩튠</option><option value="battle">기존 Tetris Battle 음악</option></select></label><label>배경음 볼륨 <b>{{ Math.round(modelValue.musicVolume*100) }}%</b><input aria-label="배경음 볼륨" type="range" min="0" max="1" step=".05" :value="modelValue.musicVolume" @input="change('musicVolume',Number(($event.target as HTMLInputElement).value))"></label><label class="sound-check"><input type="checkbox" :checked="modelValue.effects" @change="change('effects',($event.target as HTMLInputElement).checked)"> 게임 효과음 켜기</label><label>효과음 볼륨 <b>{{ Math.round(modelValue.effectsVolume*100) }}%</b><input aria-label="효과음 볼륨" type="range" min="0" max="1" step=".05" :value="modelValue.effectsVolume" @input="change('effectsVolume',Number(($event.target as HTMLInputElement).value))"></label><div class="sound-tests"><button @click="$emit('test','rotate')">회전 소리</button><button @click="$emit('test','tetris')">테트리스 소리</button><button @click="$emit('test','win')">승리 소리</button></div><small>이동 · 회전 · 낙하 · 줄 삭제 · 콤보 · 아이템 · KO · 위험 경고 · 승패. 클래식 음악은 직접 합성한 편곡입니다.</small></section></template>
<script setup lang="ts">
import type {AudioSettings,SoundEvent} from '~/game/GameAudio'
const props=defineProps<{modelValue:AudioSettings;music:boolean}>()
const emit=defineEmits<{ 'update:modelValue':[value:AudioSettings];music:[enabled:boolean];test:[event:SoundEvent] }>()
function change(key:keyof AudioSettings,value:unknown){emit('update:modelValue',{...props.modelValue,[key]:value})}
</script>
